chunk.argumentsDelta:
{"file_path":"src/nodes.js","content":"/**
 * The value model built while parsing a configuration document. Every node
 * is a plain object tagged with `type`, one of `table`, `array-of-tables`,
 * `array`, `string`, `integer`, `float` or `boolean`. Tables keep their
 * members in a `Map` to preserve insertion order and to keep unusual key
 * text (such as `__proto__`) from touching the object prototype.
 */

export function makeTable() {
  return { type: 'table', map: new Map(), headerDeclared: false }
}

export function makeArrayOfTables() {
  return { type: 'array-of-tables', items: [] }
}

export function makeArray(items) {
  return { type: 'array', items }
}

export function makeScalar(type, value) {
  return { type, value }
}

/** Joins a path's key segments the way error messages report them. */
export function pathText(parts) {
  return parts.join('.')
}
"}

