{"file_path":"src/scanner.js","content":"import { ParseError } from './errors.js'
import { makeScalar, makeArray, makeTable } from './nodes.js'

const NAME_RE = /^[A-Za-z0-9_-]+/
const HEX4_RE = /^[0-9A-Fa-f]{4}$/
const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(?:(\.[0-9]+)(?:[eE][+-]?[0-9]+)?|[eE][+-]?[0-9]+)$/

/** Delimiters that end a bare (unquoted) value token. Deliberately excludes
 * `#` and `;`: a comment marker glued to a bare value is part of that
 * value's text, per the specification, and only ends the value when
 * separated from it by whitespace. */
function isBareDelimiter(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

/** Scans one line of a configuration document, tracking a cursor position
 * so the various `parse*` methods can be composed by the document builder. */
export class Scanner {
  constructor(line, index, lineNumber) {
    this.s = line
    this.i = index
    this.line = lineNumber
  }

  fail(reason) {
    throw new ParseError(this.line, reason)
  }

  peek() {
    return this.s[this.i]
  }

  skipWS() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True once nothing meaningful remains on the line: end of text, or an
   * unquoted comment marker. */
  atEnd() {
    this.skipWS()
    return this.i >= this.s.length || this.s[this.i] === '#' || this.s[this.i] === ';'
  }

  parseDottedName() {
    const parts = []
    for (;;) {
      this.skipWS()
      parts.push(this.parseName())
      this.skipWS()
      if (this.s[this.i] === '.') {
        this.i++
        continue
      }
      break
    }
    return parts
  }

  parseName() {
    const c = this.s[this.i]
    if (c === '"') return this.scanBasicString()
    if (c === "'") return this.scanLiteralString()
    const rest = this.s.slice(this.i)
    const m = NAME_RE.exec(rest)
    if (!m) this.fail('expected a name')
    this.i += m[0].length
    return m[0]
  }

  scanBasicString() {
    this.i++ // opening quote
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.i >= this.s.length) this.fail('unterminated string')
        const e = this.s[this.i]
        if (e === '"') { out += '"'; this.i++ }
        else if (e === '\\') { out += '\\'; this.i++ }
        else if (e === 'n') { out += '\n'; this.i++ }
        else if (e === 't') { out += '\t'; this.i++ }
        else if (e === 'r') { out += '\r'; this.i++ }
        else if (e === '0') { out += '\0'; this.i++ }
        else if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!HEX4_RE.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 5
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      this.i++
    }
  }

  scanLiteralString() {
    this.i++ // opening quote
    const start = this.i
    for (;;) {
      if (this.i >= this.s.length) this.fail('unterminated string')
      if (this.s[this.i] === "'") {
        const out = this.s.slice(start, this.i)
        this.i++
        return out
      }
      this.i++
    }
  }

  /** Parses a value; `path` is the absolute key path (from the document
   * root) at which this value will live, used only if the value is itself
   * a table so its own member conflicts report the right path. */
  parseValue(path) {
    this.skipWS()
    const c = this.s[this.i]
    if (
      this.i >= this.s.length ||
      c === '#' || c === ';' || c === ',' || c === ']' || c === '}'
    ) {
      this.fail('expected a value')
    }
    if (c === '"') return makeScalar('string', this.scanBasicString())
    if (c === "'") return makeScalar('string', this.scanLiteralString())
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    const start = this.i
    while (this.i < this.s.length && !isBareDelimiter(this.s[this.i])) this.i++
    const token = this.s.slice(start, this.i)
    if (token === 'true') return makeScalar('boolean', true)
    if (token === 'false') return makeScalar('boolean', false)
    if (FLOAT_RE.test(token)) return makeScalar('float', Number(token.replace(/_/g, '')))
    if (INT_RE.test(token)) return makeScalar('integer', Number(token.replace(/_/g, '')))
    this.fail(`invalid value ${token}`)
  }

  parseArray(path) {
    this.i++ // '['
    const items = []
    this.skipWS()
    if (this.atEnd()) this.fail('unterminated array')
    if (this.s[this.i] === ']') { this.i++; return makeArray(items) }
    for (;;) {
      items.push(this.parseValue(path))
      this.skipWS()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.s[this.i] === ',') {
        this.i++
        this.skipWS()
        if (this.atEnd()) this.fail('unterminated array')
        if (this.s[this.i] === ']') { this.i++; return makeArray(items) }
        continue
      }
      if (this.s[this.i] === ']') { this.i++; return makeArray(items) }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.i++ // '{'
    const table = makeTable()
    this.skipWS()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.s[this.i] === '}') { this.i++; return table }
    for (;;) {
      this.skipWS()
      const names = this.parseDottedName()
      this.skipWS()
      if (this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      this.skipWS()
      const memberPath = path.concat(names)
      const value = this.parseValue(memberPath)
      assignInto(table, names, value, this.line, path)
      this.skipWS()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === '}') { this.i++; return table }
      this.fail('unterminated inline table')
    }
  }
}

/** Walks `names` under `startNode`, creating intermediate tables and
 * descending through the last element of an array of tables, then assigns
 * `value` at the final key. `prefix` is the absolute path to `startNode`,
 * used to report conflicts with their path from the document root. */
export function assignInto(startNode, names, value, lineNumber, prefix) {
  let node = startNode
  for (let k = 0; k < names.length - 1; k++) {
    const key = names[k]
    let child = node.map.get(key)
    if (child === undefined) {
      child = makeTable()
      node.map.set(key, child)
    } else if (child.type === 'table') {
      // descend
    } else if (child.type === 'array-of-tables') {
      child = child.items[child.items.length - 1]
    } else {
      const at = prefix.concat(names.slice(0, k + 1))
      throw new ParseError(lineNumber, `${at.join('.')} is not a table`)
    }
    node = child
  }
  const lastKey = names[names.length - 1]
  if (node.map.has(lastKey)) {
    const at = prefix.concat(names)
    throw new ParseError(lineNumber, `key ${at.join('.')} is defined twice`)
  }
  node.map.set(lastKey, value)
}
"}

