{"file_path":"src/output.js","content":"/** Renders a parsed document (its root table node) as canonical JSON,
 * indented by two spaces, with object members in ascending key order by
 * code point and a trailing newline. */
export function toJSON(root) {
  return render(root, 0) + '\n'
}

function sortedKeys(map) {
  return Array.from(map.keys()).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
}

function render(node, indent) {
  const pad = '  '.repeat(indent)
  const childPad = '  '.repeat(indent + 1)
  if (node.type === 'table') {
    const keys = sortedKeys(node.map)
    if (keys.length === 0) return '{}'
    const entries = keys.map(
      (k) => `${childPad}${JSON.stringify(k)}: ${render(node.map.get(k), indent + 1)}`
    )
    return `{\n${entries.join(',\n')}\n${pad}}`
  }
  if (node.type === 'array' || node.type === 'array-of-tables') {
    const items = node.items
    if (items.length === 0) return '[]'
    const entries = items.map((item) => `${childPad}${render(item, indent + 1)}`)
    return `[\n${entries.join(',\n')}\n${pad}]`
  }
  // string, integer, float, boolean
  return JSON.stringify(node.value)
}

/** Renders the `keys` view: one `<path> <type>` line per node below the
 * root, depth first, objects in ascending key order and arrays in index
 * order, each node reported before its children. */
export function toKeys(root) {
  const lines = []
  for (const key of sortedKeys(root.map)) {
    emit(key, root.map.get(key), lines)
  }
  return lines.join('')
}

function typeName(node) {
  if (node.type === 'table') return 'table'
  if (node.type === 'array' || node.type === 'array-of-tables') return 'array'
  return node.type
}

function emit(path, node, lines) {
  lines.push(`${path} ${typeName(node)}\n`)
  if (node.type === 'table') {
    for (const key of sortedKeys(node.map)) {
      emit(`${path}.${key}`, node.map.get(key), lines)
    }
  } else if (node.type === 'array' || node.type === 'array-of-tables') {
    node.items.forEach((item, i) => {
      emit(`${path}[${i}]`, item, lines)
    })
  }
}
