{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { parseDocument } from './document.js'
import { toJSON, toKeys } from './output.js'
import { ParseError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require_fs()
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // Lazily imported so the module stays ESM-friendly while using a
  // synchronous read for stdin.
  return fsModule
}

import * as fsModule from 'node:fs'

function main() {
  const [mode] = process.argv.slice(2)
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const output = mode === 'json' ? toJSON(root) : toKeys(root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

